from pathlib import Path
import json

root = Path(__file__).resolve().parents[1]
data = json.loads((root / 'content/workbook-winemaking.json').read_text())
template = Path(__file__).with_name('workbook-winemaking.js').read_text()
(root / 'dist/workbook-winemaking.js').write_text(
    '/* Generated by scripts/build-workbook-winemaking.py. */\nconst winemakingWorkbook='
    + json.dumps(data, ensure_ascii=False, indent=1) + ';\n' + template)
print(f"Built {len(data['questions'])} original workbook questions.")
